import java.util.Scanner;

public class Main {
    static int gap(int a, int b) {
        if (a < b) {
            return b - a;
        }
        return a - b;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int a = input.nextInt();
        int b = input.nextInt();
        System.out.println(gap(a, b));
    }
}

